        JPanel main=new JPanel(new BorderLayout());main.setBackground(BG);JPanel top=new JPanel(new BorderLayout());top.setBackground(BG);top.setBorder(BorderFactory.createEmptyBorder(22,28,16,28));JLabel heading=new JLabel("WEALTH MANAGEMENT  /  OVERVIEW");heading.setFont(new Font("SansSerif",Font.BOLD,15));heading.setForeground(GOLD);top.add(heading,BorderLayout.WEST);summary.setForeground(new Color(195,195,188));summary.setFont(new Font("SansSerif",Font.PLAIN,11));top.add(summary,BorderLayout.EAST);main.add(top,BorderLayout.NORTH);
